function twinXor(values) {
  const zero = [0], one = [0];
  const insert = (v) => {
    let node = 0;
    for (let bit = 30; bit >= 0; bit--) {
      const side = (v >> bit) & 1 ? one : zero;
      if (!side[node]) { side[node] = zero.length; zero.push(0); one.push(0); }
      node = side[node];
    }
  };
  const bestFor = (v) => {
    let node = 0, result = 0;
    for (let bit = 30; bit >= 0; bit--) {
      const want = (v >> bit) & 1 ? zero : one;
      if (want[node]) { result |= 1 << bit; node = want[node]; }
      else node = (want === zero ? one : zero)[node];
    }
    return result;
  };
  insert(values[0]);
  let best = 0;
  for (let i = 1; i < values.length; i++) {
    best = Math.max(best, bestFor(values[i]));
    insert(values[i]);
  }
  return best;
}
